import 'section_help_data.dart';

/// One piece of plain-language help: a [title] and a [body].
class HelpEntry {
  const HelpEntry(this.title, this.body);

  final String title;
  final String body;
}

/// Help copy for every section card and figure in the app.
///
/// The web wording lives in `webapp/src/lib/glossary.ts` and is mirrored in
/// `section_help_data.dart` (generated by `tool/gen_section_help.py`). Entries
/// written only for Flutter live in [kFlutterOnlyHelp] below, in the same
/// voice: what it shows, how it is worked out, what to do with it.
///
/// Keys are `<page>.<section>` for sections and a bare word (`xirr`) for
/// glossary terms, so the two namespaces cannot collide.
abstract final class SectionHelp {
  static const Map<String, HelpEntry> all = {
    ...kWebSectionHelp,
    ...kFlutterOnlyHelp,
    ...kGlossary,
  };

  /// The entry for [key]. Throws in debug if the key is unknown, so a typo
  /// fails loudly in tests instead of silently showing no help.
  static HelpEntry of(String key) {
    final e = all[key];
    assert(e != null, 'No help entry for "$key"');
    return e ?? const HelpEntry('Help', 'No description is available yet.');
  }
}

